"use client";

import Image from "next/image";
import { useEffect, useState } from "react";

const NAV_ITEMS = [
  { label: "Home", href: "#home" },
  { label: "About", href: "#about" },
  { label: "Live Events", href: "#live-events" },
  { label: "Music", href: "#music" },
  { label: "Videos", href: "#videos" },
  { label: "Charts", href: "#charts" },
  { label: "Merch", href: "#merch" },
];

type SocialPlatform = "instagram" | "facebook" | "twitter" | "youtube";

const SOCIAL_LINKS: Array<{
  label: string;
  href: string;
  platform: SocialPlatform;
}> = [
  { label: "Instagram", href: "https://instagram.com", platform: "instagram" },
  { label: "Facebook", href: "https://facebook.com", platform: "facebook" },
  { label: "Twitter", href: "https://twitter.com", platform: "twitter" },
  { label: "YouTube", href: "https://youtube.com", platform: "youtube" },
];

function SocialIcon({ platform }: { platform: SocialPlatform }) {
  if (platform === "instagram") {
    return (
      <svg viewBox="0 0 24 24" aria-hidden="true">
        <rect
          x="3"
          y="3"
          width="18"
          height="18"
          rx="5"
          stroke="currentColor"
          fill="none"
          strokeWidth="1.8"
        />
        <circle cx="12" cy="12" r="4.2" fill="none" stroke="currentColor" strokeWidth="1.8" />
        <circle cx="17.3" cy="6.7" r="1.15" fill="currentColor" />
      </svg>
    );
  }

  if (platform === "facebook") {
    return (
      <svg viewBox="0 0 24 24" aria-hidden="true">
        <path
          d="M13.4 7.6h2.3V4.2h-2.7c-3 0-4.2 1.9-4.2 4.4v2.2H6.2v3.3h2.6v6h3.7v-6h2.8l.4-3.3h-3.2V9c0-.9.4-1.4 1-1.4Z"
          fill="currentColor"
        />
      </svg>
    );
  }

  if (platform === "twitter") {
    return (
      <svg viewBox="0 0 24 24" aria-hidden="true">
        <path
          d="M22 5.8c-.7.3-1.4.5-2.2.6.8-.5 1.3-1.2 1.6-2.1-.8.5-1.6.8-2.5 1a4.2 4.2 0 0 0-7.1 3.8A12 12 0 0 1 3 4.7a4.2 4.2 0 0 0 1.3 5.6c-.6 0-1.2-.2-1.7-.5 0 2 1.3 3.8 3.2 4.3-.3.1-.7.2-1.1.2-.3 0-.5 0-.8-.1.5 1.7 2.1 2.9 4 3A8.5 8.5 0 0 1 2 19c1.9 1.2 4.2 1.9 6.6 1.9 7.9 0 12.2-6.5 12.2-12.2v-.6c.8-.5 1.5-1.3 2.1-2.1Z"
          fill="currentColor"
        />
      </svg>
    );
  }

  return (
    <svg viewBox="0 0 24 24" aria-hidden="true">
      <rect
        x="2.5"
        y="5.2"
        width="19"
        height="13.6"
        rx="3"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.8"
      />
      <path d="m10.4 9 5.1 3-5.1 3V9Z" fill="currentColor" />
    </svg>
  );
}

export default function SiteHeader() {
  const [isScrolled, setIsScrolled] = useState(false);
  const [activeHash, setActiveHash] = useState("#home");

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 50);
    };

    const syncHash = () => {
      setActiveHash(window.location.hash || "#home");
    };

    handleScroll();
    syncHash();
    window.addEventListener("scroll", handleScroll, { passive: true });
    window.addEventListener("hashchange", syncHash);

    return () => {
      window.removeEventListener("scroll", handleScroll);
      window.removeEventListener("hashchange", syncHash);
    };
  }, []);

  return (
    <header className={`site-header${isScrolled ? " is-scrolled" : ""}`}>
      <a className="brand" href="#home" aria-label="Celtic Worship">
        <Image
          className="brand-logo"
          src="/CELTIC-WORSHIP-LOGO-smaller-1-600x35.png"
          alt="Celtic Worship"
          width={600}
          height={35}
          priority
        />
      </a>

      <nav className="main-nav" aria-label="Main">
        {NAV_ITEMS.map((item) => (
          <a
            key={item.href}
            className={activeHash === item.href ? "is-active" : undefined}
            href={item.href}
            aria-current={activeHash === item.href ? "page" : undefined}
            onClick={() => setActiveHash(item.href)}
          >
            {item.label}
          </a>
        ))}
      </nav>

      <nav className="header-socials" aria-label="Social media">
        {SOCIAL_LINKS.map((item) => (
          <a
            key={item.label}
            className="social-link"
            href={item.href}
            target="_blank"
            rel="noopener noreferrer"
            aria-label={item.label}
          >
            <SocialIcon platform={item.platform} />
          </a>
        ))}
      </nav>
    </header>
  );
}
